//! Domains: lexicon, stopwords and corpus statistics for one arXiv category.
//!
//! A domain directory contains (all optional):
//! - `curated.toml`  hand-written lexicon, always wins over mined entries
//! - `mined.toml`    lexicon generated by `scitok-learn build`
//! - `reviewed.toml` LLM-reviewed lexicon from `scitok-learn refine`; used instead of
//!   `mined.toml` when present
//! - `stats.toml`    corpus statistics (average document length for BM25)
//! - `stopwords.txt` extra stopwords, one per line, `#` comments

use std::fmt;
use std::path::Path;

use serde::{Deserialize, Serialize};

use crate::lexicon::TermDef;

/// Version of the domain file format. Changing how domain data maps to terms
/// changes the term ids of an existing index, so mismatches are rejected.
pub const FORMAT_VERSION: u32 = 1;

include!(concat!(env!("OUT_DIR"), "/builtin_domains.rs"));

#[derive(Debug)]
pub struct Error(pub String);

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.0)
    }
}

impl std::error::Error for Error {}

#[derive(Debug, Default, Deserialize, Serialize)]
pub struct LexiconFile {
    pub version: u32,
    #[serde(default)]
    pub term: Vec<TermDef>,
}

#[derive(Clone, Debug, Default, Deserialize, Serialize, PartialEq)]
pub struct Stats {
    pub version: u32,
    pub category: String,
    pub from: String,
    pub until: String,
    pub generated_by: String,
    /// Number of abstracts (title + abstract) in the corpus.
    pub docs: usize,
    /// Average tokenized length of title + abstract.
    pub avg_len: f32,
    #[serde(default)]
    pub fulltext_docs: usize,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub avg_len_fulltext: Option<f32>,
}

#[derive(Clone, Debug, Default)]
pub struct Domain {
    pub name: String,
    pub curated: Vec<TermDef>,
    pub mined: Vec<TermDef>,
    pub stopwords: Vec<String>,
    pub stats: Option<Stats>,
}

impl Domain {
    /// A domain compiled into the library (see the `domain-*` cargo features).
    pub fn builtin(name: &str) -> Result<Domain, Error> {
        let (_, [curated, mined, stats, stopwords, reviewed]) = BUILTIN
            .iter()
            .find(|(n, _)| *n == name)
            .ok_or_else(|| Error(format!("unknown built-in domain {name:?}; available: {:?}", Domain::builtin_names())))?;
        Domain::from_sources(name, *curated, reviewed.or(*mined), *stats, *stopwords)
    }

    pub fn builtin_names() -> Vec<&'static str> {
        BUILTIN.iter().map(|(n, _)| *n).collect()
    }

    /// Load a domain directory, e.g. one written by `scitok-learn`.
    pub fn load(dir: impl AsRef<Path>) -> Result<Domain, Error> {
        let dir = dir.as_ref();
        if !dir.is_dir() {
            return Err(Error(format!("domain directory {} does not exist", dir.display())));
        }
        let read = |file: &str| -> Result<Option<String>, Error> {
            let path = dir.join(file);
            match std::fs::read_to_string(&path) {
                Ok(s) => Ok(Some(s)),
                Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(None),
                Err(e) => Err(Error(format!("{}: {e}", path.display()))),
            }
        };
        let name = dir.file_name().map(|n| n.to_string_lossy().into_owned()).unwrap_or_default();
        Domain::from_sources(
            &name,
            read("curated.toml")?.as_deref(),
            read("reviewed.toml")?.or(read("mined.toml")?).as_deref(),
            read("stats.toml")?.as_deref(),
            read("stopwords.txt")?.as_deref(),
        )
    }

    pub fn from_sources(
        name: &str,
        curated: Option<&str>,
        mined: Option<&str>,
        stats: Option<&str>,
        stopwords: Option<&str>,
    ) -> Result<Domain, Error> {
        let lexicon = |src: Option<&str>, file: &str| -> Result<Vec<TermDef>, Error> {
            let Some(src) = src else { return Ok(Vec::new()) };
            let parsed: LexiconFile = toml::from_str(src).map_err(|e| Error(format!("{name}/{file}: {e}")))?;
            check_version(parsed.version, name, file)?;
            Ok(parsed.term)
        };
        let stats = match stats {
            Some(src) => {
                let s: Stats = toml::from_str(src).map_err(|e| Error(format!("{name}/stats.toml: {e}")))?;
                check_version(s.version, name, "stats.toml")?;
                Some(s)
            }
            None => None,
        };
        Ok(Domain {
            name: name.to_owned(),
            curated: lexicon(curated, "curated.toml")?,
            mined: lexicon(mined, "mined.toml")?,
            stopwords: stopwords.map(parse_word_list).unwrap_or_default(),
            stats,
        })
    }
}

fn check_version(version: u32, name: &str, file: &str) -> Result<(), Error> {
    if version != FORMAT_VERSION {
        return Err(Error(format!(
            "{name}/{file}: format version {version}, this scitok reads version {FORMAT_VERSION}; \
             regenerate the domain (and re-index, since term ids change)"
        )));
    }
    Ok(())
}

pub(crate) fn parse_word_list(src: &str) -> Vec<String> {
    src.lines()
        .map(|l| l.split('#').next().unwrap().trim())
        .filter(|l| !l.is_empty())
        .map(str::to_lowercase)
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn rejects_other_versions() {
        let err = Domain::from_sources("x", Some("version = 2\n"), None, None, None).unwrap_err();
        assert!(err.0.contains("format version 2"), "{err}");
    }

    #[test]
    fn reviewed_replaces_mined() {
        let dir = std::env::temp_dir().join(format!("scitok-domain-reviewed-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let def = |c: &str| format!("version = 1\n[[term]]\ncanonical = \"{c}\"\nvariants = [\"{c}\"]\n");
        std::fs::write(dir.join("mined.toml"), def("raw")).unwrap();
        assert_eq!(Domain::load(&dir).unwrap().mined[0].canonical, "raw");
        std::fs::write(dir.join("reviewed.toml"), def("reviewed")).unwrap();
        assert_eq!(Domain::load(&dir).unwrap().mined[0].canonical, "reviewed");
        std::fs::remove_dir_all(dir).unwrap();
    }

    #[test]
    fn parses_sources() {
        let d = Domain::from_sources(
            "x",
            Some("version = 1\n[[term]]\ncanonical = \"qaoa\"\nvariants = [\"QAOA\"]\n"),
            None,
            None,
            Some("# comment\nFoo\n\nbar # trailing\n"),
        )
        .unwrap();
        assert_eq!(d.curated[0].canonical, "qaoa");
        assert_eq!(d.stopwords, vec!["foo", "bar"]);
    }

    #[cfg(feature = "domain-quant-ph")]
    #[test]
    fn builtin_quant_ph() {
        assert!(Domain::builtin_names().contains(&"quant-ph"));
        assert!(!Domain::builtin("quant-ph").unwrap().curated.is_empty());
        assert!(Domain::builtin("nope").is_err());
    }
}
